using System;using System.Collections.Generic;public class Solution{public IList<int> CountSmaller(int[]a){int[]v=(int[])a.Clone();Array.Sort(v);var rank=new Dictionary<int,int>();int z=0;foreach(int x in v)if(!rank.ContainsKey(x))rank[x]=++z;int[]b=new int[z+1],o=new int[a.Length];for(int i=a.Length-1;i>=0;i--){int r=rank[a[i]];for(int x=r-1;x>0;x-=x&-x)o[i]+=b[x];for(int x=r;x<=z;x+=x&-x)b[x]++;}return o;}}
